if(t==='height')return '<div class=control><label>Height</label><input id=h type=number min=1 placeholder="e.g. 800"></div><div class=control><label>Output</label><select id=fmt><option value=image/png>PNG</option><option value=image/jpeg>JPG</option><option value=image/webp>WebP</option></select></div>';
if(t==='percent')return '<div class=control><label>Scale</label><div class=range><input id=p type=range min=10 max=300 value=100><span class=rv id=pv>100%</span></div></div><div class=control><label>Output</label><select id=fmt><option value=image/png>PNG</option><option value=image/jpeg>JPG</option><option value=image/webp>WebP</option></select></div>';
